"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["36056"],{89650(e){e.exports=JSON.parse('{"id":"FIN-785","slug":"forward-guidance","term":"Forward Guidance","also_known_as":[],"difficulty":"Intermediate","definition":"Forward guidance is communication by a central bank about the likely future path of its monetary policy, such as how long interest rates are expected to stay at a certain level, to influence expectations and financial conditions today.","explanation":["Interest rates on mortgages, business loans and bonds depend not only on the current policy rate but also on what people expect future rates to be. By signalling its intentions, a central bank can shape those expectations.","For example, a central bank might say that it expects to keep interest rates low until unemployment falls below a certain level or until inflation is sustainably back at target. If markets believe this, long-term interest rates may fall, making borrowing cheaper even without an immediate rate cut.","Forward guidance became an important tool after the 2008 financial crisis, when interest rates were close to zero and central banks needed other ways to support the economy.","It can take different forms, from general statements about the direction of policy to specific commitments linked to dates or economic conditions. Its effectiveness depends on credibility. If circumstances change and the central bank has to break its guidance, it can confuse markets and damage trust in future communications."],"note":"","total":1725,"prev":{"slug":"forward-contract","term":"Forward Contract"},"next":{"slug":"forward-p-e","term":"Forward P/E"}}')}}]);